// Generated status table of the product specs (docs/specs/product/readme.md).
// Derives the counts per epic from the spec files themselves (story headings `### US-<EPIC>-nn · … · ✅|🟨|⬜`
// and requirement rows `| FR-<EPIC>-nn | … | ✅|🟨|⬜ |`), so a PR only changes its own epic's row.
// Usage: node app/tools/dev/agent/spec-status.mjs [--write|--print|--check]   (default: --write)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const START =
  "<!-- spec-status:start (generated by app/tools/dev/agent/spec-status.mjs, do not edit by hand) -->";
export const END = "<!-- spec-status:end -->";
const MARK = /[⬜🟨✅]/u;
const EPICS = {
  ACC: "Accounts",
  BES: "Collection",
  LIC: "Light and locations",
  PHA: "Care phases",
  WAC: "Growth/photos",
  BEH: "Treatments",
  WUN: "Wishlist",
  POK: "Pokédex",
  MON: "Reminders/sensors",
  SOZ: "Social",
  EQU: "Equipment",
  KI: "AI access",
  QS: "Cross-cutting",
  MIG: "Migration (dropped)",
  ENT: "Discover",
  QG: "Quality gates",
  DEV: "Development process",
  ACH: "Achievements",
  TAU: "Swipe matching",
  ONB: "Introduction and unlocking",
};

/** @param {string[]} texts contents of the numbered spec files */
export function collect(texts) {
  const rows = new Map(
    Object.keys(EPICS).map((e) => [
      e,
      {
        us: { "✅": 0, "🟨": 0, "⬜": 0 },
        fr: { "✅": 0, "🟨": 0, "⬜": 0 },
        tried: 0,
        stories: 0,
      },
    ]),
  );
  for (const line of texts.flatMap((t) => t.split("\n"))) {
    const story = line.match(/^#{2,4} US-([A-Z]+)-\d+ ·.*?([⬜🟨✅])/u);
    if (story && rows.has(story[1])) {
      const r = rows.get(story[1]);
      r.stories++;
      r.us[story[2]]++;
      if (/\(prototype [✅🟡]/u.test(line)) r.tried++;
      continue;
    }
    const req = line.match(/^\| FR-([A-Z]+)-\d+ \|/);
    if (req && rows.has(req[1])) {
      const cells = line
        .split("|")
        .map((c) => c.trim())
        .filter(Boolean);
      const mark = cells[cells.length - 1].match(MARK)?.[0];
      if (mark) rows.get(req[1]).fr[mark]++;
    }
  }
  return rows;
}

export function render(rows) {
  const head = [
    "Epic",
    "Stories",
    "✅",
    "🟨",
    "⬜",
    "Requirements ✅ · 🟨 · ⬜",
    "Tried in the prototype",
    "New",
  ];
  const body = [];
  const tot = { s: 0, a: 0, b: 0, c: 0, t: 0 };
  for (const [epic, r] of rows) {
    if (!r.stories) {
      body.push([`${epic} ${EPICS[epic]}`, "0", "0", "0", "0", fmtFr(r.fr), "0", "0"]);
      continue;
    }
    body.push(
      [
        `${epic} ${EPICS[epic]}`,
        r.stories,
        r.us["✅"],
        r.us["🟨"],
        r.us["⬜"],
        fmtFr(r.fr),
        r.tried,
        r.stories - r.tried,
      ].map(String),
    );
    tot.s += r.stories;
    tot.a += r.us["✅"];
    tot.b += r.us["🟨"];
    tot.c += r.us["⬜"];
    tot.t += r.tried;
  }
  body.push([
    "**Total**",
    ...[tot.s, tot.a, tot.b, tot.c].map((n) => `**${n}**`),
    "",
    `**${tot.t}**`,
    `**${tot.s - tot.t}**`,
  ]);
  const all = [head, ...body];
  const w = head.map((_, i) => Math.max(...all.map((r) => width(r[i]))));
  const line = (r) => `| ${r.map((c, i) => String(c) + " ".repeat(w[i] - width(c))).join(" | ")} |`;
  return [line(head), `| ${w.map((n) => "-".repeat(n)).join(" | ")} |`, ...body.map(line)].join(
    "\n",
  );
}

// Prettier counts the status emoji as two columns wide; the same widths keep the table stable under `make format`.
const width = (c) => [...String(c)].reduce((n, ch) => n + (MARK.test(ch) ? 2 : 1), 0);
const fmtFr = (f) => `${f["✅"]} · ${f["🟨"]} · ${f["⬜"]}`;

/** Replaces the block between the markers; returns null when the markers are missing. */
export function replaceBlock(readme, table) {
  const s = readme.indexOf(START);
  const e = readme.indexOf(END);
  if (s < 0 || e < s) return null;
  return `${readme.slice(0, s)}${START}\n\n${table}\n\n${readme.slice(e)}`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const mode = process.argv[2] ?? "--write";
  const dir = fileURLToPath(new URL("../../../../docs/specs/product/", import.meta.url));
  const texts = fs
    .readdirSync(dir)
    .filter((n) => /^\d\d-.*\.md$/.test(n))
    .sort()
    .map((n) => fs.readFileSync(path.join(dir, n), "utf8"));
  const table = render(collect(texts));
  if (mode === "--print") console.log(table);
  else {
    const file = path.join(dir, "readme.md");
    const old = fs.readFileSync(file, "utf8");
    const next = replaceBlock(old, table);
    if (next === null) {
      console.error(`spec-status: markers missing in ${file}`);
      process.exit(2);
    }
    if (mode === "--check") {
      if (next !== old) {
        console.error("spec-status: table is stale, run the script without arguments");
        process.exit(1);
      }
    } else {
      fs.writeFileSync(file, next);
      console.log("spec-status: updated");
    }
  }
}
